AssistantMessageToolRequest(name='create', tool_call_id='tooluse_TNBROGvzePS1UW7iJuJLtn', arguments={'file_text': 'const form = document.getElementById('quizForm');
const successMessage = document.getElementById('successMessage');
const questionFieldsets = document.querySelectorAll('fieldset');

form.addEventListener('submit', (e) => {
  e.preventDefault();

  let isValid = true;
  const questions = ['question1', 'question2', 'question3'];

  questions.forEach((questionName) => {
    const checkboxes = document.querySelectorAll(`input[name="${questionName}"]`);
    const errorElement = document.getElementById(`q${questionName.slice(-1)}-error`);
    const fieldset = Array.from(questionFieldsets).find(fs =>
      fs.querySelector(`input[name="${questionName}"]`)
    );

    const isChecked = Array.from(checkboxes).some(cb => cb.checked);

    if (!isChecked) {
      isValid = false;
      errorElement.textContent = 'Error: Please select at least one answer.';
      errorElement.hidden = false;
      if (fieldset) {
        fieldset.setAttribute('aria-describedby', 
          `${fieldset.getAttribute('aria-describedby') || ''} ${errorElement.id}`.trim());
      }
    } else {
      errorElement.hidden = true;
      if (fieldset) {
        const currentDescribedBy = fieldset.getAttribute('aria-describedby') || '';
        const updated = currentDescribedBy.replace(errorElement.id, '').trim();
        if (updated) {
          fieldset.setAttribute('aria-describedby', updated);
        } else {
          fieldset.removeAttribute('aria-describedby');
        }
      }
    }
  });

  if (isValid) {
    form.hidden = true;
    successMessage.hidden = false;
    successMessage.focus();
  }
});

document.querySelectorAll('input[type="checkbox"]').forEach(checkbox => {
  checkbox.addEventListener('change', () => {
    const questionName = checkbox.name;
    const errorElement = document.getElementById(`q${questionName.slice(-1)}-error`);
    errorElement.hidden = true;
  });
});
