const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  try {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.resolve(__dirname, 'index.html');
    let htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    // Read axe script
    const axeScript = fs.readFileSync('/tmp/axe.min.js', 'utf-8');

    // Inject axe and configure it before closing body
    htmlContent = htmlContent.replace('</body>', `<script>\n${axeScript}\nwindow.axeConfig = { branding: 'off' };\n</script>\n</body>`);

    await page.goto('file://' + htmlPath, { waitUntil: 'domcontentloaded' });

    // Inject axe into the page after load
    await page.evaluate((script) => {
      return new Promise((resolve) => {
        const scriptEl = document.createElement('script');
        scriptEl.textContent = script;
        document.body.appendChild(scriptEl);
        setTimeout(resolve, 100);
      });
    }, axeScript);

    // Wait for axe to be ready
    await page.waitForTimeout(500);

    // Now run axe
    const results = await page.evaluate('() => new Promise(resolve => window.axe.run((error, results) => resolve(results)))');

    console.error('Got results:', !!results);

    await browser.close();

    if (!results || !results.violations) {
      console.error('No violations array');
      process.exit(1);
    }

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
      wcag: wcag.map(v => ({
        id: v.id,
        impact: v.impact,
        description: v.description,
        targets: v.nodes.map(n => n.target)
      })),
      bp: bp.map(v => ({
        id: v.id,
        description: v.description,
        targets: v.nodes.map(n => n.target)
      }))
    }, null, 2));

    process.exit(wcag.length > 0 ? 1 : 0);
  } catch (err) {
    console.error('Error:', err.message);
    process.exit(1);
  }
})();
